CREATE OR REPLACE TABLE conductor_s_execution AS
WITH cleaned_papers AS (
  SELECT paper_id,
         TRIM(REPLACE(year, '"', '')) AS year_str
  FROM papers
), p2009 AS (
  SELECT paper_id FROM cleaned_papers WHERE year_str = '2009' OR CAST(NULLIF(year_str, '') AS INTEGER) = 2009
), pa AS (
  SELECT paper_id, author_id FROM paper_author
), joined_2009 AS (
  SELECT pa.author_id
  FROM pa INNER JOIN p2009 USING(paper_id)
), counts_2009 AS (
  SELECT author_id, COUNT(*) AS paper_count FROM joined_2009 GROUP BY author_id
), top_2009 AS (
  SELECT author_id, paper_count FROM counts_2009 ORDER BY paper_count DESC, author_id ASC LIMIT 1
), any_2009 AS (
  SELECT COUNT(*) AS c FROM counts_2009
), overall_counts AS (
  SELECT author_id, COUNT(*) AS paper_count FROM pa GROUP BY author_id
), top_overall AS (
  SELECT author_id, paper_count FROM overall_counts ORDER BY paper_count DESC, author_id ASC LIMIT 1
)
SELECT a.name AS author_name, t.paper_count, '2009' AS scope
FROM top_2009 t
JOIN any_2009 k ON k.c > 0
LEFT JOIN authors a ON a.author_id = t.author_id
UNION ALL
SELECT a2.name AS author_name, tovr.paper_count, 'overall_no_2009' AS scope
FROM top_overall tovr
JOIN any_2009 k ON k.c = 0
LEFT JOIN authors a2 ON a2.author_id = tovr.author_id;

